css:
#clock-wrapper { position: absolute; top: 0; left: 0; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; overflow: hidden; }
#flip-clock { display: flex; align-items: center; justify-content: center; gap: 15px; }
#colon { font-weight: bold; line-height: 1; display: none; margin: 0 5px; }
.digit-card { position: relative; width: 200px; height: 260px; border-radius: 12px; perspective: 1000px; box-shadow: 0 12px 30px rgba(0,0,0,0.5); }
.digit-card .top, .digit-card .bottom, .digit-card .flip-top, .digit-card .flip-bottom {
  position: absolute; left: 0; width: 100%; height: 50%; overflow: hidden; display: flex; justify-content: center; box-sizing: border-box;
}
.digit-card .top, .digit-card .flip-top {
  top: 0; border-top-left-radius: 12px; border-top-right-radius: 12px; align-items: flex-end; border-bottom: 1px solid rgba(0,0,0,0.6);
}
.digit-card .bottom, .digit-card .flip-bottom {
  bottom: 0; border-bottom-left-radius: 12px; border-bottom-right-radius: 12px; align-items: flex-start; border-top: 1px solid rgba(255,255,255,0.1);
}
.digit-card span { position: absolute; height: 200%; display: flex; align-items: center; justify-content: center; width: 100%; line-height: 1; font-weight: bold; }
.digit-card .top span, .digit-card .flip-top span { top: 0; }
.digit-card .bottom span, .digit-card .flip-bottom span { bottom: 0; }
.digit-card .flip-top { transform-origin: bottom; backface-visibility: hidden; z-index: 3; }
.digit-card .flip-bottom { transform-origin: top; backface-visibility: hidden; z-index: 2; transform: rotateX(90deg); }
.digit-card .hinge { position: absolute; top: 50%; left: 0; width: 100%; height: 2px; background: rgba(0,0,0,0.8); transform: translateY(-50%); z-index: 4; }

render:
const { root, params, progress, duration, time, width, height } = ctx;
const wrapper = root.querySelector('#clock-wrapper');
const clock = root.querySelector('#flip-clock');
const colon = root.querySelector('#colon');

if (wrapper) wrapper.style.backgroundColor = params.bg_color;

const isMMSS = params.format === 'MM:SS';
if (colon) colon.style.display = isMMSS ? 'block' : 'none';

const cardM1 = root.querySelector('#card-m1');
const cardM2 = root.querySelector('#card-m2');
if (cardM1) cardM1.style.display = isMMSS ? 'block' : 'none';
if (cardM2) cardM2.style.display = isMMSS ? 'block' : 'none';

const totalSec = params.start_sec;
const currentTotalTime = Math.max(0, totalSec - (progress * totalSec));
const currentSecInt = Math.floor(currentTotalTime);
const nextSecInt = Math.max(0, currentSecInt - 1);

const secFraction = currentTotalTime - currentSecInt; 
const flipWindow = Math.min(0.9, params.flip_speed);
const flipProgress = secFraction < flipWindow ? (1 - (secFraction / flipWindow)) : 0;

function getDigits(val) {
  const m = Math.floor(val / 60);
  const s = Math.floor(val % 60);
  const mStr = String(m).padStart(2, '0');
  const sStr = String(s).padStart(2, '0');
  return { m1: mStr[0], m2: mStr[1], s1: sStr[0], s2: sStr[1], fullS: String(val).padStart(2, '0') };
}

const curDigits = getDigits(currentSecInt);
const nextDigits = getDigits(nextSecInt);

const cards = [
  { el: root.querySelector('#card-m1'), cur: curDigits.m1, next: nextDigits.m1, show: isMMSS },
  { el: root.querySelector('#card-m2'), cur: curDigits.m2, next: nextDigits.m2, show: isMMSS },
  { el: root.querySelector('#card-s1'), cur: isMMSS ? curDigits.s1 : curDigits.fullS[0], next: isMMSS ? nextDigits.s1 : nextDigits.fullS[0], show: true },
  { el: root.querySelector('#card-s2'), cur: isMMSS ? curDigits.s2 : curDigits.fullS[1], next: isMMSS ? nextDigits.s2 : nextDigits.fullS[1], show: true }
];

const h = params.card_size;
const w = Math.round(h * 0.72);
const fontSize = Math.round(h * 0.82);

if (colon) {
  colon.style.fontSize = fontSize + 'px';
  colon.style.color = params.text_color;
  colon.style.fontFamily = params.font_family;
}

cards.forEach(c => {
  if (!c.el || !c.show) return;
  c.el.style.width = w + 'px';
  c.el.style.height = h + 'px';

  const tops = c.el.querySelectorAll('.top, .flip-top');
  const bottoms = c.el.querySelectorAll('.bottom, .flip-bottom');

  c.el.querySelectorAll('.top, .bottom, .flip-top, .flip-bottom').forEach(part => {
    part.style.backgroundColor = params.card_color;
  });

  c.el.querySelectorAll('span').forEach(sp => {
    sp.style.color = params.text_color;
    sp.style.fontFamily = params.font_family;
    sp.style.fontSize = fontSize + 'px';
  });

  const topStatic = c.el.querySelector('.top span');
  const bottomStatic = c.el.querySelector('.bottom span');
  const flipTop = c.el.querySelector('.flip-top');
  const flipTopSpan = c.el.querySelector('.flip-top span');
  const flipBottom = c.el.querySelector('.flip-bottom');
  const flipBottomSpan = c.el.querySelector('.flip-bottom span');

  const isFlipping = c.cur !== c.next && flipProgress > 0;

  if (!isFlipping) {
    if (topStatic) topStatic.textContent = c.cur;
    if (bottomStatic) bottomStatic.textContent = c.cur;
    if (flipTop) flipTop.style.transform = 'rotateX(0deg)';
    if (flipBottom) flipBottom.style.transform = 'rotateX(90deg)';
    if (flipTopSpan) flipTopSpan.textContent = c.cur;
    if (flipBottomSpan) flipBottomSpan.textContent = c.next;
  } else {
    if (topStatic) topStatic.textContent = c.next;
    if (bottomStatic) bottomStatic.textContent = c.cur;
    if (flipTopSpan) flipTopSpan.textContent = c.cur;
    if (flipBottomSpan) flipBottomSpan.textContent = c.next;

    if (flipProgress <= 0.5) {
      const topDeg = flipProgress * 2 * 90;
      if (flipTop) flipTop.style.transform = `rotateX(-${topDeg}deg)`;
      if (flipBottom) flipBottom.style.transform = 'rotateX(90deg)';
    } else {
      const botDeg = 90 - ((flipProgress - 0.5) * 2 * 90);
      if (flipTop) flipTop.style.transform = 'rotateX(-90deg)';
      if (flipBottom) flipBottom.style.transform = `rotateX(${botDeg}deg)`;
    }
  }
});
